{
  "chapter": 6,
  "sections": [
    {
      "section": "6.1",
      "cuts": [557, 571, 582, 588, 597, 602],
      "paragraphs": [
        {"start": 557, "end": 570, "ending": "影响家庭甚至国家历史的是天上的场景，人所争取的资源对自己的影响力其实没那么大", "title": "约伯记1章6至8节把镜头从人可见的约伯家产、家庭和睦转到天上，说明有些关乎家庭的事在人看不见的灵界，真正影响家庭甚至国家历史的是天上的场景，人所争取的物质资源和情感维系其实非常脆弱"},
        {"start": 571, "end": 581, "ending": "皇帝坐在上面，众大臣站在下面集会，这被称为早朝", "title": "约伯记1章6节是整件事的转折点，神的众子聚集在耶和华面前；神的众子就是众天使的意思，这个场景好像君王听政的集会，如同康熙王朝、雍正王朝中皇帝坐在上面、众大臣站在下面早朝一样"},
        {"start": 582, "end": 587, "ending": "撒旦原来就是这种性质的活物，只不过他背叛了上帝", "title": "很多人不明白撒旦怎么也能来到天上，解释撒旦原是堕落的天使，他原本就是这种属灵气的活物，只是背叛了上帝"},
        {"start": 588, "end": 596, "ending": "撒旦已经不是神的众子之一了，他怎么也来了", "title": "撒旦本来是天使，但堕落以后确实不在神的众子队伍之中；作者用「也来在其中」的措辞暗示撒旦已不是神的众子之一，只是他也来了"},
        {"start": 597, "end": 601, "ending": "撒旦在这个队伍中是个不协调的成员", "title": "以高湖教会集会时陈世美也来在其中为例，说明这话的意思是陈世美不是高湖的却怎么也来了；神的众子是一个队伍，撒旦也来在其中，是不协调的成员"},
        {"start": 602, "end": 604, "ending": "他不在这个集会的合法成员之内", "title": "结论是撒旦已经不是神的众子，已经不是天使，但他原本确实是受造的这种属灵气的活物，只是不在这个集会的合法成员之内"}
      ],
      "uncertain": [
        {"line": 597, "reason": "597「这话什么意思？」引出598的高湖教会例子，按自问自答和过渡句归后处理"}
      ]
    },
    {
      "section": "6.2",
      "cuts": [605, 613, 619, 630, 636, 647, 654],
      "paragraphs": [
        {"start": 605, "end": 612, "ending": "很多人困惑，因为找他搭话搞得约伯这么惨，上帝有些做法很难理解", "title": "许多人不理解约伯记1章7节：撒旦来就来，为什么耶和华不把他赶走，反而主动询问他「你从哪里来」；很多人因此困惑，因为找他搭话搞得约伯这么惨，上帝有些做法很难理解"},
        {"start": 613, "end": 618, "ending": "神不跟他这样讲，撒旦是没有办法主动开口的", "title": "直接说出结论：这不是一次搭讪，也不是一次找茬，而是一次讲话的授权；要表达的是撒旦自始至终都在上帝的权下，神不这样讲，撒旦没有办法主动开口"},
        {"start": 619, "end": 629, "ending": "这是一种说话的授权", "title": "用约伯记1章7节和2章2节上帝两次问同样的问题「你从哪里来」，说明这不是上帝困惑，而是授权撒旦回答，是一种说话的授权"},
        {"start": 630, "end": 635, "ending": "不能有一个人突然间站起来主动跟皇帝说话", "title": "以皇帝上早朝时大臣太监说「有事启奏，无事退朝」为例，说明这话的意思是现在可以说话了，不能在皇帝上朝时有人突然站起来主动跟皇帝说话"},
        {"start": 636, "end": 646, "ending": "耶和华主动发问，给他一个发言的授权，撒旦才能得到说话的权利", "title": "以公司跟领导开会、小孩子到课堂为例，说明在权柄底下要举手授权才能说话；耶和华集会时撒旦不可能冲进去主动说话，耶和华主动用同样语式问「你从哪里来」，给他发言授权，撒旦才有说话的权利"},
        {"start": 647, "end": 653, "ending": "第一次不能伤他的身体，第二次能伤身体但不能夺走性命，都在限制之下，这种限制贯穿整个约伯记", "title": "耶和华出于某种荣耀的目的给撒旦一定的活动权限让他说话，但魔鬼完全在神的掌管之中；后面攻击约伯时都受耶和华权柄限制，第一次不能伤身体，第二次能伤身体但不能夺走性命，这种对邪恶的限制贯穿整个约伯记"},
        {"start": 654, "end": 660, "ending": "相信当下还在被上帝掌控，就不会有任何的不安稳感", "title": "如果确知又确信撒旦肆虐的当下正被上帝良善的权柄限制，神的儿女对上帝的期待、信心和安稳感就不只建立在解脱困境之后，还会建立在正在困境之中，因为相信当下仍在上帝掌控中，就不会有不安稳感"}
      ],
      "uncertain": []
    },
    {
      "section": "6.3",
      "cuts": [661, 667],
      "paragraphs": [
        {"start": 661, "end": 666, "ending": "本来撒旦就是控告者，你还要说这个人有多好", "title": "约伯记1章8节耶和华主动称赞约伯完全正直、远离恶事，引出困惑：这不是主动引魔鬼攻击义人吗？很多弟兄姊妹都有这样的困惑，撒旦这么凶，本来撒旦就是控告者，你还要说这个人有多好"},
        {"start": 667, "end": 677, "ending": "耶和华主动借着他的邪恶来授权他，并且促成自己美善的计划，是哪一种", "title": "借着读经时感觉不痛快来思考两个选择题：是认为耶和华主动要撒旦注意约伯，还是撒旦本来就在关注约伯；耶和华主动借撒旦的邪恶来授权他，并且促成自己美善的计划，是哪一种"}
      ],
      "uncertain": []
    },
    {
      "section": "6.4",
      "cuts": [678, 685, 695, 700],
      "paragraphs": [
        {"start": 678, "end": 684, "ending": "魔鬼不是全知全能，这段圣经中有证据", "title": "教会大部分时间介绍上帝，极少介绍魔鬼，但至少要知道魔鬼不是全知全能；全宇宙中只有一位全知、全能、全在，就是耶和华上帝，魔鬼不是全知全能，这段圣经中有证据"},
        {"start": 685, "end": 694, "ending": "全在只有一位可能性就是上帝", "title": "魔鬼从创世以前、始祖的时候就在，似乎不受时间限制、不会老，但他受空间限制；约伯记1章7节魔鬼自己说「我从地上走来走去，往返而来」，意思是他若在东方就一定不在西边，不能认为魔鬼是全在的，全在只有上帝"},
        {"start": 695, "end": 699, "ending": "这叫做空间限制，要去那边只能从这里走过去，往返而来", "title": "以耶稣所说「从天降下却仍就在天的人子」为例，说明宇宙中没有这样的存在物，除了上帝；人只要在这里就不在那边，因为受空间限制，要去那边只能从这里走过去，往返而来"},
        {"start": 700, "end": 704, "ending": "他不需要往返，他充满全地，耶和华的荣耀", "title": "上帝可以说自己在东也在西，超乎众人之上、贯乎众人之中、也住在众人之间，道成肉身仍就在天，用全能的命令托住万有；他不需要往返，他充满全地，耶和华的荣耀"}
      ],
      "uncertain": []
    },
    {
      "section": "6.5",
      "cuts": [705, 712, 721],
      "paragraphs": [
        {"start": 705, "end": 711, "ending": "撒旦从地上来，走来走去往返而来", "title": "耶和华问撒旦从哪里来、从什么空间来、是什么样的活物，撒旦非常诚实地回答从地上来；他已经不在天上，神的众子在天上，撒旦从地上来，走来走去往返而来"},
        {"start": 712, "end": 720, "ending": "他既然不是全在的，也不是全知的，就要走到约伯身边", "title": "介绍撒旦受空间限制，因为他在东方就不在西方，必须走来走去；如果他了解约伯的信息，后面又把约伯的状况说得那么清楚，说明这些年他在约伯身边，因为除了上帝没有一位全在的，撒旦不是全在也不是全知，就要走到约伯身边"},
        {"start": 721, "end": 730, "ending": "撒旦一直盯着约伯，因为他不是一个全知者", "title": "撒旦对约伯了解，后面约伯记1章9节之后他说出约伯家里的情况，问「他敬畏你岂是无故呢？难道你不是四面圈上篱笆保护他吗？」；撒旦不是全知者，他需要走来走去，一直在约伯身边盯着约伯"}
      ],
      "uncertain": []
    },
    {
      "section": "6.6",
      "cuts": [731, 741, 750, 758, 765],
      "paragraphs": [
        {"start": 731, "end": 740, "ending": "上帝对约伯的评价是敬畏我、远离恶事，不会错", "title": "撒旦对约伯敬畏神的原因两次提出质疑，耶和华两次都允许他去试验，但撒旦对约伯内心的评估出错；上帝全知全能全在，也全然无误，对约伯的评价是敬畏我、远离恶事，不会错"},
        {"start": 741, "end": 749, "ending": "约伯浑身烂疮之后依然持守纯正，撒旦第二次又错了", "title": "撒旦第一次质疑说夺去约伯所有的，他必当面弃掉神，结果约伯说赏赐的是耶和华，收取的是耶和华，耶和华的名是应当称颂的，出乎撒旦意料；撒旦第二次说人以皮代骨，击打他身体他必弃掉神，结果约伯浑身烂疮之后依然持守纯正，第二次又错了"},
        {"start": 750, "end": 757, "ending": "第二次猜应该是皮肉，骨头又错了", "title": "撒旦两次出错，上帝不会两次出错；撒旦对人的观察需要知识积累，第一次姑且认为约伯因钱财才敬畏神，钱财拿掉后却意外发现约伯仍敬畏神，第二次又猜应该是皮肉，结果又错了"},
        {"start": 758, "end": 764, "ending": "他永远都是在上帝面前，是在权下的姿态", "title": "撒旦很厉害，我们搞不过他，但千万不要把他放成跟上帝掰腕子；网上有耶稣和撒旦在桌子上掰手腕的图，这不可能，他怎么可能跟上帝坐到一张桌子上来，他永远在上帝面前是权下的姿态，受造的天使再高级也不可能是耶和华这样"},
        {"start": 765, "end": 775, "ending": "他对约伯也不全然了解，但他在约伯旁边，本身就想试探约伯", "title": "耶和华在天上就了解约伯，对约伯的评价从头到尾没有出现任何差错；人类才需要日久见人心，需要年日积累才能了解人，但耶和华从开始就知道约伯透透的；撒旦不全知也不全在，对约伯也不全然了解，但他在约伯旁边，本身就想试探约伯"}
      ],
      "uncertain": []
    },
    {
      "section": "6.7",
      "cuts": [776, 783, 794, 801],
      "paragraphs": [
        {"start": 776, "end": 782, "ending": "招灾的一定是恶人，义人一定要得福才对，约伯的三个朋友后面也都是这样认为", "title": "上帝完全认可约伯对他的敬畏，却两次允许约伯受祸，而且灾祸非常严重；大部分人都想不明白，因为他们认为招灾的一定是恶人，义人一定要得福才对，约伯的三个朋友后面也都是这样认为"},
        {"start": 783, "end": 793, "ending": "义人有可能受苦，恶人却有可能亨通，具备这种智慧就会有健全的信心", "title": "约伯记讨论了一个非常需要讨论的主题，就是义人受苦、恶人亨通的怪单，这事在智慧书、诗篇、先知书中反复出现；圣经诚实地告诉人义人有可能受苦，恶人却有可能亨通，具备这种智慧之后就能有一个健全的信心"},
        {"start": 794, "end": 800, "ending": "没有人敢拿敬畏神以后家破人亡来说事，但上帝自己就记载了这个事", "title": "正常人选择任何一个宗教都以保佑顺遂和福泽作为敬拜的理由，哪一个庙宇不是以灵验作为招牌；基督教的见证也基本上清一色讲信耶稣以后丰收了某些东西，没有人敢拿敬畏神以后家破人亡来说事，但上帝自己就记载了这个事"},
        {"start": 801, "end": 810, "ending": "义人可能受苦，恶人可能亨通，是上帝告诉你的，在这个不正常的世界，你们的人生可能这样", "title": "有人用约伯记结尾约伯双倍得回祝福来反驳，但路加福音财主和拉撒路比喻中的乞丐拉撒路长烂疮，狗舔他的疮，至死没得回，死后在亚伯拉罕的怀里；不要以为最终盼望又变成祝福，义人可能受苦，恶人可能亨通，是上帝告诉你的，在这个不正常的世界，你们的人生可能这样"}
      ],
      "uncertain": []
    },
    {
      "section": "6.8",
      "cuts": [811, 815, 822, 830, 839, 844],
      "paragraphs": [
        {"start": 811, "end": 814, "ending": "我们的福音是这个，不是别的东西", "title": "更重要的东西是解脱这几十年，福音是不可废去之福，我们的福音是这个，不是别的东西"},
        {"start": 815, "end": 821, "ending": "我们老祖宗都通过观察懂得这个道理", "title": "以中国老祖宗的话「好人不长命，王八活千年」为例，王八指坏人，坏人反而家大业大，老祖宗都通过观察懂得这个道理"},
        {"start": 822, "end": 829, "ending": "不能因一个人顺风顺水就认可他的信仰，因为上帝可能不认可他", "title": "这决定基督徒不能因为灾难就怀疑自己或别人的信仰，因为上帝可能认可他；也不能因为一个人顺风顺水就认可他的信仰，因为上帝可能不认可他，圣经中亦有这种例子"},
        {"start": 830, "end": 838, "ending": "对福音的误解会导致完全错信一场，这是非常不好也非常遗憾的东西", "title": "当说信仰的方式需要调整时，有人用人生顺遂比如家里买了三套房子来回应，这是鸡同鸭讲；不要把处境放在自己信仰的纯正度上，对福音的误解会导致完全错信一场，有人用家庭和睦或事业高升公然拒绝反思自己的信仰，这是非常不好也非常遗憾的东西"},
        {"start": 839, "end": 843, "ending": "两个都不可取，你得信智慧书一定给你带来智慧", "title": "有的人明明错了却因家庭或人生顺遂的处境拒绝反思，有的人明明对了却因突然遭灾开始怀疑自己，两个都不可取，要信智慧书一定给你带来智慧"},
        {"start": 844, "end": 850, "ending": "顺遂与祸福跟上帝对你的认可与否是两码事", "title": "用当下环境来解释信仰的实质是一种误区，用环境作为对信仰正与反的解释，熟知智慧书的基督徒绝不可能同意；顺遂与祸福跟上帝对某人的认可与否是两码事，光这一点愚昧就有很多人都有"}
      ],
      "uncertain": []
    },
    {
      "section": "6.9",
      "cuts": [851, 859, 869, 879, 885],
      "paragraphs": [
        {"start": 851, "end": 858, "ending": "一件事，一个现实，会有两种解释", "title": "举例说明，假如有人要来教会讲道，前一天腿摔断又连续拉肚子，有人认为上帝在拦阻不要去，另一拨人认为撒旦在拦阻要坚持去，一件事一个现实产生两种解释"},
        {"start": 859, "end": 868, "ending": "同一件事居然分出两拨人，给出两种解释", "title": "讲员亲身经历过，在做关乎上帝的工作时身体出问题，比如发烧或骑车摔了，结果两拨人给出两种解释：生病是上帝拦阻不要去，或生病是撒旦拦阻更要去，同一件事分出两拨人"},
        {"start": 869, "end": 878, "ending": "人随私意解读，不只随私意解读圣经，还会随私意解读环境", "title": "让人不知到底听谁的，借着物质指着灵界来论就是愚昧；但很多人喜欢这样做，一般说上帝拦阻的人通常是自己不想去，说撒旦拦阻的人是自己想去，人随私意解读，不只随私意解读圣经，还会随私意解读环境"},
        {"start": 879, "end": 884, "ending": "天上场景和地下场景完全没什么关系，有的都是上帝自己的美意和圣言", "title": "讲员身上所发生的事可能跟上帝的旨意没有半毛钱关系，不要硬扯在一起，有时有有时没有，不要一定要对应；从约伯记就会发现，天上的场景和地下的场景完全没什么关系，有的都是上帝自己的美意和圣言"},
        {"start": 885, "end": 889, "ending": "眼前显明的东西不表示背后属灵的实际，生病不代表这个人就是坏", "title": "当走上某一条道路时，环境不要成为第一参考标准，因为有些时候在你眼前显明的东西不表示背后属灵的实际，生病不代表这个人就是坏，解读上帝的旨意不要这样"}
      ],
      "uncertain": []
    },
    {
      "section": "6.10",
      "cuts": [890, 899, 911, 919],
      "paragraphs": [
